import { describe, it, expect } from 'vitest';
import { packetTextToSections } from './packetPrint';

// A miniature packet in the exact grammar the lifecycle builders emit:
// divider band + title, a `Key : value` header block, numbered `N. EN · AR`
// sections, and a `Generated by …` footer.
const SAMPLE = [
  '────────────────',
  'AUDIT COMMITTEE EXECUTIVE PACKET',
  'حزمة لجنة المراجعة التنفيذية',
  '────────────────',
  'Reporting entity: ACME Bank',
  'الجهة          : بنك أكمي',
  'Quarter        : Q3-2026',
  'Generated      : 2026-07-08T12:00:00Z',
  '',
  '1. ANNUAL AUDIT PLAN STATUS · حالة خطة التدقيق السنوية',
  '   Plan ID  : AP-2026 (2026)',
  '   Status   : APPROVED',
  '',
  '2. FINDINGS BY SEVERITY · الملاحظات بحسب الخطورة',
  '   CRITICAL    : 2',
  '   HIGH        : 5',
  '',
  '────────────────',
  'Generated by TSS GRC Platform',
  '────────────────',
].join('\n');

describe('packetTextToSections', () => {
  it('splits into Overview + numbered sections, dropping the title band and footer', () => {
    const s = packetTextToSections(SAMPLE);
    expect(s.map(x => x.titleEn)).toEqual(['Overview', 'ANNUAL AUDIT PLAN STATUS', 'FINDINGS BY SEVERITY']);
    expect(s[1].titleAr).toBe('حالة خطة التدقيق السنوية');
    expect(s.every(x => x.structured)).toBe(true);
    // the title band and footer credit are NOT emitted as content
    expect(s.some(x => x.titleEn.includes('EXECUTIVE PACKET'))).toBe(false);
    expect(JSON.stringify(s)).not.toContain('Generated by TSS GRC');
  });

  it('renders Key : value lines as two-column rows', () => {
    const s = packetTextToSections(SAMPLE);
    expect(s[0].body).toContain('<span class="k">Reporting entity</span>');
    expect(s[0].body).toContain('<span class="v">ACME Bank</span>');
    expect(s[1].body).toContain('<span class="k">Plan ID</span>');
    expect(s[2].body).toContain('<span class="k">CRITICAL</span>');
  });

  it('escapes HTML in values', () => {
    const s = packetTextToSections('1. X · س\n   Note : <b>a</b> & c');
    expect(s[0].body).toContain('&lt;b&gt;a&lt;/b&gt; &amp; c');
    expect(s[0].body).not.toContain('<b>a</b>');
  });

  it('falls back to a single section for unstructured text', () => {
    const s = packetTextToSections('just some text\nno structure here');
    expect(s.length).toBe(1);
    expect(s[0].structured).toBeUndefined();
  });
});
